def min_absolute_value(X, K, D):
    # If K is even, Takahashi can always return to the origin
    if K % 2 == 0:
        return 0
    # If K is odd, the best strategy is to move in such a way that minimizes the absolute value
    # This can be achieved by moving in one direction until reaching the nearest multiple of D
    remainder = abs(X) % D
    # If the remainder is zero, the absolute value is already minimized
    if remainder == 0:
        return 0
    # Otherwise, the minimum absolute value is the smaller of the two possible moves
    else:
        return min(remainder, D - remainder)

